insert into public.hard_sector_sections(sector,section_key,body) values('construction','hero','{"badgeAr":"هارد للمقاولات العامة والإنشائية","badgeEn":"HARD General Contracting & Construction Development","headlineAr":"نبني صروح المستقبل بأعلى معايير الهندسة والإتقان","headlineEn":"Building the Future with Supreme Engineering Standards & Mastery","subtitleAr":"المقاولات العامة والإنشاءات الكبرى والتشطيبات الفاخرة وإدارة المشاريع المتكاملة للمشاريع السكنية والتجارية في المنطقة الشرقية.","subtitleEn":"General contracting, landmark construction, ultra-luxury fit-out, and turnkey project governance across the Eastern Province.","bgImageUrl":"https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1600&q=80","stats":{"projectsCount":"٤٥+","buaM2Total":"١٨٠,٠٠٠+ م²","safetyHours":"١.٥ مليون+ ساعة","satisfactionRate":"٩٩.٤٪"},"ctaPrimaryAr":"استعراض المشاريع الإنشائية","ctaPrimaryEn":"Explore Construction Projects","ctaSecondaryAr":"حاسبة التكلفة التقديرية","ctaSecondaryEn":"Cost Estimator Calculator","isPublished":true}'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('construction','company','{"crNumber":"1010894231","taxId":"300192847100003","momrahClassificationAr":"تصنيف فئة أولى (المقاولات العامة)","momrahClassificationEn":"Class-A Classified General Contractor","sceAccreditationAr":"هيئة المهندسين السعوديين - اعتماد رقم #44091","sceAccreditationEn":"Saudi Council of Engineers Accredited #44091","sbcComplianceAr":"١٠٠٪ مطابقة كود البناء السعودي (SBC)","sbcComplianceEn":"100% Saudi Building Code (SBC) Compliant","structuralWarrantyAr":"ضمان إنشائي معتمد لمدة ١٠ سنوات","structuralWarrantyEn":"10-Year Certified Structural Warranty","aboutTitleAr":"شريكك الهندسي الموثوق في البناء والتشييد المتكامل","aboutTitleEn":"Your Trusted Engineering Partner in Integrated Construction","aboutTextAr":"تأسست مؤسسة عبد المحسن الدوسري (هارد) للمقاولات لتكون ركيزة أساسية في قطاع المقاولات والإنشاءات بالمنطقة الشرقية، حيث نجمع بين الخبرة الهندسية المتعمقة وأحدث المعدات والتقنيات الإنشائية لتقديم مشاريع متكاملة من التخطيط والتصميم وحتى تسليم المفتاح بأعلى معايير كود البناء السعودي.","aboutTextEn":"Abdul Mohsen Al Dosari Establishment (HARD) was founded as a cornerstone in the Eastern Province’s contracting and construction sector, combining deep engineering expertise with state-of-the-art machinery to deliver turnkey projects adhering strictly to the Saudi Building Code (SBC).","visionAr":"أن نكون الخيار الأول في قطاع المقاولات العامة والإنشاءات الكبرى عبر تقديم حلول هندسية مبتكرة ومستدامة تلبي تطلعات رؤية السعودية ٢٠٣٠.","visionEn":"To be the premier choice in general contracting and major engineering construction by providing innovative and sustainable engineering solutions aligned with Saudi Vision 2030.","missionAr":"التزام مطلق بالجودة والسلامة والدقة المتناهية في المواعيد، وتسليم صروح إنشائية ترتقي بمستويات المعيشة والاستثمار.","missionEn":"Absolute commitment to quality, safety, and deadline precision, delivering structural landmarks that elevate living and investment standards.","isPublished":true}'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('construction','stages','[{"id":"stage-1","order":1,"titleAr":"الحفر والأساسات والهيكل العظم","titleEn":"Excavation, Raft & Superstructure","durationAr":"٣ - ٥ أشهر","durationEn":"3 - 5 Months","descriptionAr":"أعمال الحفر العميق، صب الخرسانات سابقة الإجهاد، بناء الأعمدة والأسقف Flat Slabs.","descriptionEn":"Deep excavation, post-tensioned raft foundations, column casting, and flat slabs erection.","deliverablesAr":["اختبارات التربة والخرسانة","شهادة عزل الأساسات","مطابقة SBC الهندسي"],"deliverablesEn":["Soil & Concrete Testing","Foundation Waterproofing Cert","SBC Compliance Inspection"],"iconName":"Building2"},{"id":"stage-2","order":2,"titleAr":"أنظمة الكهروميكانيك MEP والتأسيس","titleEn":"MEP Infrastructure & Rough-In","durationAr":"٢ - ٣ أشهر","durationEn":"2 - 3 Months","descriptionAr":"تأسيس شبكات التكييف المركزي VRF، السباكة الضغط العالي، التغذية الكهربائية والمنزل الذكي.","descriptionEn":"VRF HVAC ducting installation, high-pressure plumbing, electrical wiring & KNX smart home tubing.","deliverablesAr":["مخططات As-Built المعتمدة","اختبارات الضغط الهيدروليكي","تأسيسات التكييف المخفي"],"deliverablesEn":["Approved As-Built Shop Drawings","Hydraulic Pressure Test Reports","HVAC Rough-In Approval"],"iconName":"Cpu"},{"id":"stage-3","order":3,"titleAr":"التشطيبات الفاخرة والواجهات","titleEn":"Turnkey Luxury Fit-Out & Facades","durationAr":"٤ - ٦ أشهر","durationEn":"4 - 6 Months","descriptionAr":"تكسيات الحجر الطبيعي والواجهات الزجاجية ثلاثية الطبقات، أرضيات الرخام الإيطالي، والأسقف الديكورية.","descriptionEn":"Riyadh stone cladding, triple-glazed curtain walls, Italian Statuario marble & bespoke ceilings.","deliverablesAr":["عزل الواجهات والأسطح","تركيب الرخام والأخشاب","أنظمة الإضاءة المعمارية"],"deliverablesEn":["Facade & Roof Thermal Proofing","Marble & Joinery Installation","Architectural Lighting Setup"],"iconName":"Layers"},{"id":"stage-4","order":4,"titleAr":"الفحص النهائي والتسليم وضمان ١٠ سنوات","titleEn":"Final Inspection, Handover & 10Y Warranty","durationAr":"١ شهر","durationEn":"1 Month","descriptionAr":"تشغيل واختبار الأنظمة بالكفاءة القصوى، استخراج شهادة الإشغال البلدي، وتسليم وثائق الضمان الإنشائي.","descriptionEn":"Full system commissioning, municipal completion certificate issuance, and 10-year structural warranty package.","deliverablesAr":["وثيقة الضمان الإنشائي ١٠ سنوات","شهادة إتمام البناء","كتيب التشغيل والصيانة"],"deliverablesEn":["10-Year Structural Warranty Certificate","Building Occupancy Permit","O&M Manuals"],"iconName":"ShieldCheck"}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('construction','offices','[{"id":"hq-dammam","nameAr":"المقر الرئيسي – الدمام","nameEn":"Head Office – Dammam","addressAr":"طريق الأمير متعب بن عبد العزيز، حي هجر، الدمام، المملكة العربية السعودية","addressEn":"Prince Mutaib bin Abdulaziz Road, Hajar District, Dammam, Saudi Arabia","phone":"+966 55 612 5711","mobile":"","whatsapp":"+966556125711","email":"info@hardgp.com","lat":0,"lng":0,"googleMapsUrl":"","isHQ":true}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('construction','services','[{"id":"turnkey-construction","iconName":"Building2","titleAr":"بناء عظم وتسليم مفتاح متكامل","titleEn":"Turnkey Design & Build Construction","subtitleAr":"من المخطط وحتى استلام المفتاح مع ضمان شامل","subtitleEn":"From initial excavation to turnkey handover with warranty","descriptionAr":"تنفيذ شامل للمشاريع السكنية والتجارية يشمل أعمال الحفر والأساسات، العظم الخرساني، والتسليم المفتاح بأعلى معايير كود البناء السعودي مع إشراف هندسي مستمر.","descriptionEn":"End-to-end execution of residential villas and commercial complexes, encompassing deep excavation, reinforced concrete superstructure, MEP engineering, and luxury turnkey delivery.","deliverablesAr":["إشراف هندسي يومي معتمد من كبار المهندسين الاستشاريين","استخدام خرسانات معتمدة ومطابقة للاختبارات المخبرية (Cube Testing)","ضمان شامل لمدة ١٠ سنوات على الهيكل الإنشائي والعوازل","جدول زمني إلكتروني دقيق مع تقارير تقدم دورية موثقة بالصور والفيديو"],"deliverablesEn":["Daily certified engineering supervision by licensed consultants","High-spec tested readymix concrete with certified lab reports","10-year comprehensive structural & waterproofing warranty","Digital timeline tracking with weekly high-res photo/video logs"],"warrantyYears":10,"badgeAr":"الخدمة الأكثر طلباً","badgeEn":"Most Popular","startingPriceSAR":"١,٤٥٠ ر.س / م²"},{"id":"structural-civil","iconName":"Layers","titleAr":"الأعمال الإنشائية والخرسانية الكبرى","titleEn":"Structural & Heavy Civil Engineering","subtitleAr":"أساسات عميقة، خوازيق، وبلاطات سابقة الإجهاد","subtitleEn":"Deep piling, PT slabs, and high-strength concrete framing","descriptionAr":"تنفيذ الهياكل الخرسانية المسلحة، الخوازيق وسند جوانب الحفر، البلاطات سابقة الإجهاد (Post-Tension)، والهياكل المعدنية الثقيلة للمباني الشاهقة والمستودعات.","descriptionEn":"Specialized in heavy civil structures, deep secant/tangent pile shoring, post-tensioned floor systems, and heavy structural steel erection for high-rise towers and industrial facilities.","deliverablesAr":["دراسات وفحوصات ميكانيكا التربة واختبارات التحميل (CBR & Piling)","تقنيات صب متطورة للخرسانات الكتلية ذات الحرارة المنخفضة","حديد تسليح سابك معتمد بدرجات مقاومة عالية للزلازل والرياح","تقارير الجودة والسلامة المهنية المعتمدة دولياً"],"deliverablesEn":["Geotechnical soil investigation & pile load testing verification","Low-heat mass concrete pouring technology for thermal control","Certified SABIC rebar with high ductility seismic resistance","International QA/QC safety auditing and non-destructive testing"],"warrantyYears":10,"badgeAr":"معتمد SBC","badgeEn":"SBC Certified","startingPriceSAR":"٦٥٠ ر.س / م²"},{"id":"luxury-finishing","iconName":"Sparkles","titleAr":"التشطيبات الفندقية والديكور المعماري","titleEn":"Ultra-Luxury Fit-Out & Interior Architecture","subtitleAr":"رخام طبيعي، خشب معماري، وواجهات زجاجية حديثة","subtitleEn":"Natural marble, architectural millwork & modern glazing","descriptionAr":"تنفيذ تشطيبات داخلية وخارجية فائقة الفخامة للقصور والفلل والمقرات الإدارية، تشمل الرخام الإيطالي، النجارة المعمارية، الواجهات الزجاجية، والتكسيات الخارجية.","descriptionEn":"Exquisite interior and exterior finishing for high-end residences, corporate headquarters, and hotels, integrating imported Italian marble, bespoke joinery, and structural glazing.","deliverablesAr":["تصميم وتنفيذ لوحات الرخام المتطابق (Book-Matched Marble)","أبواب مخفية ونجارة معمارية مخصصة بخشب الجوز والبلوط الطبيعي","واجهات ألمنيوم وزجاج ثلاثي عازل للصوت والحرارة بأعلى تصنيف","تجهيز أنظمة الإنارة المعمارية الذكية DALI و KNX"],"deliverablesEn":["Precision book-matched marble slab fabrication & floor laying","Concealed flush doors and bespoke American walnut joinery","Triple-glazed thermal-break acoustic aluminum curtain walls","Integrated DALI smart architectural lighting scenes"],"warrantyYears":5,"badgeAr":"جودة VIP","badgeEn":"VIP Luxury","startingPriceSAR":"١,١٠٠ ر.س / م²"},{"id":"mep-hvac","iconName":"Wrench","titleAr":"الأعمال الكهروميكانيكية والتكييف (MEP)","titleEn":"Electro-Mechanical & Modern HVAC (MEP)","subtitleAr":"أنظمة التكييف المركزي VRF والشبكات الذكية","subtitleEn":"Central VRF air conditioning, plumbing & electrical grid","descriptionAr":"تصميم وتنفيذ متكامل لكافة الأنظمة الكهربائية، الصحية، التكييف المركزي (Chillers & VRF)، وتوزيع الطاقة مع مطابقة كاملة لاشتراطات شركة الكهرباء والمياه والدفاع المدني.","descriptionEn":"Turnkey electrical, mechanical, plumbing, and HVAC systems installation for commercial and residential developments with full SEC, NWC, and Civil Defense approvals.","deliverablesAr":["حسابات الأحمال الحرارية الدقيقة وفق معايير ASHRAE العالمية","تمديدات نحاس مولر أمريكي وعوازل مجاري هواء عالية الكثافة","لوحات توزيع كهربائية ذكية مع حوافظ قواطع Schneider/ABB","اعتماد رسمي من الدفاع المدني لكافة أنظمة الإنذار والإطفاء"],"deliverablesEn":["ASHRAE-standard thermal load calculations and airflow CFD","Mueller USA copper piping and closed-cell acoustic duct lining","Schneider Electric / ABB certified switchgear & distribution panels","Official Civil Defense certification for fire alarm & suppression"],"warrantyYears":5,"badgeAr":"كفاءة طاقة","badgeEn":"Energy Efficient","startingPriceSAR":"٤٥٠ ر.س / م²"},{"id":"renovation-heritage","iconName":"Hammer","titleAr":"الترميم والتطوير المعماري الشامل","titleEn":"Structural Renovation & Architectural Retrofit","subtitleAr":"تحديث المباني القائمة وتدعيم العناصر الإنشائية","subtitleEn":"Modernizing existing structures & structural carbon-fiber retrofitting","descriptionAr":"تحديث وترميم المباني القائمة، تدعيم الأعمدة والأساسات بألياف الكربون (Carbon Fiber CFRP)، وإعادة تصميم الواجهات القديمة لتتحول إلى تحف معمارية عصرية تواكب رؤية ٢٠٣٠.","descriptionEn":"Structural rehabilitation and architectural rejuvenation of existing facilities, carbon-fiber structural strengthening (CFRP), and modern facade re-skinning.","deliverablesAr":["فحص واختبار السلامة الإنشائية بالموجات فوق الصوتية (NDT Testing)","تدعيم خرساني معتمد يرفع قدرة التحمل الإنشائية حتى ٨٠٪","إزالة الحوائط القديمة وتوسيع المساحات الداخلية بأمان تام","إعادة تصميم الواجهات بتكسيات حديثة معزولة (Cladding / Stone)"],"deliverablesEn":["Ultrasonic Non-Destructive Testing (NDT) structural integrity audit","Certified CFRP carbon-fiber reinforcement boosting capacity up to 80%","Safe structural load-transfer for open-plan space modernization","Modern insulated facade re-cladding with engineered stone/porcelain"],"warrantyYears":5,"badgeAr":"تطوير مستدام","badgeEn":"Modernization","startingPriceSAR":"٧٥٠ ر.س / م²"},{"id":"value-engineering","iconName":"Calculator","titleAr":"الهندسة القيمة ودراسات الجدوى والمناقصات","titleEn":"Value Engineering & Feasibility BOQ Studies","subtitleAr":"تقليل تكاليف البناء بنسبة تصل إلى ٢٥٪ دون المساس بالجودة","subtitleEn":"Cost optimization reducing up to 25% without compromising quality","descriptionAr":"مراجعة وتدقيق المخططات الهندسية وجداول الكميات (BOQ)، واقتراح بدائل إنشائية ومعمارية ذكية توفر مئات الآلاف من الريالات مع الحفاظ على أعلى معايير الأمان والمتانة.","descriptionEn":"Systematic engineering optimization of structural drawings and Bill of Quantities (BOQ), eliminating redundancies and saving substantial capital expenditure.","deliverablesAr":["تدقيق جداول الكميات والتحقق من واقعية أسعار بنود التوريد والتركيب","اقتراح بدائل للخرسانات والحديد تسهم في خفض التكلفة المادية والزمنية","نماذج نمذجة معلومات البناء 4D BIM لكشف وتفادي التعارضات قبل الصب","تقرير رسمي مفصل بحجم التوفير المالي المحقق لكل مرحلة"],"deliverablesEn":["Comprehensive BOQ audit and vendor pricing validation","Smart structural alternatives cutting cost and critical path time","4D BIM clash-detection eliminating on-site re-work costs","Detailed financial optimization report quantifying exact phase savings"],"warrantyYears":1,"badgeAr":"توفير استثماري","badgeEn":"High ROI","startingPriceSAR":"استشارة متخصصة"}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('hvac','hero','{"badgeEn":"24/7 Rapid Emergency Response & Engineering Care","badgeAr":"خدمة طوارئ واستجابة هاتفية على مدار الساعة ٢٤/٧","headlineEn":"Professional AC Maintenance and Cooling to the Highest Standards","headlineAr":"صيانة وغسيل أجهزة التكييف والتبريد بأعلى معايير الدقة والاحترافية","subtitleEn":"Specialized engineers and technicians provide comprehensive AC washing, complex fault repairs, and air duct sanitization with reliable periodic maintenance contracts in the Eastern Province.","subtitleAr":"كوادر هندسية وفنية متخصصة تقدم غسيل شامل لأجهزة التكييف، صيانة الأعطال المعقدة، وتعقيم مجاري الهواء مع عقود صيانة دورية موثوقة في المنطقة الشرقية.","bgImageUrl":"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=1600&q=80","ctaPrimaryEn":"Book Technician Visit","ctaPrimaryAr":"حجز موعد فني صيانة","ctaEmergencyEn":"Emergency Hotline Call","ctaEmergencyAr":"الاتصال بالطوارئ فوراً","isPublished":true}'::jsonb) on conflict(sector,section_key) do nothing;
