insert into public.hard_sector_sections(sector,section_key,body) values('hvac','booking_copy','{"modalTitleEn":"Schedule HVAC Service Visit","modalTitleAr":"حجز زيارة صيانة تكييف معتمدة","modalSubtitleEn":"Select your preferred time window and emergency level. Our team dispatches certified technicians.","modalSubtitleAr":"اختر الموعد المناسب ودرجة الاستعجال، وسيقوم فريقنا الفني بالتواصل ومباشرة الطلب فوراً.","urgentNoteEn":"Urgent requests receive priority hotline dispatch within 30-45 minutes.","urgentNoteAr":"الطلبات العاجلة تحظى بأولوية المباشرة الفورية خلال ٣٠ - ٤٥ دقيقة.","submitButtonEn":"Confirm Service Reservation","submitButtonAr":"تأكيد حجز الموعد الفني"}'::jsonb) on conflict(sector,section_key) do nothing;
