insert into public.hard_sector_sections(sector,section_key,body) values('hvac','work_gallery','[{"id":"gal-1","image":"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=1000&q=80","titleEn":"VRF Outdoor Multi-Unit Maintenance","titleAr":"صيانة وفحص أنظمة التبريد المتغير VRF","categoryEn":"Commercial VRF","categoryAr":"أنظمة تجارية","captionEn":"Quarterly overhaul and compressor pressure balancing in Al Khobar Tower.","captionAr":"صيانة دورية شاملة وموازنة ضغوط الكمبروسرات لبرج إداري في الخبر.","locationEn":"Al Khobar","locationAr":"الخبر","active":true},{"id":"gal-2","image":"https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=1000&q=80","titleEn":"Deep Chemical Coil Decontamination","titleAr":"الغسيل الكيميائي العميق لملفات المكثف","categoryEn":"Deep Cleaning","categoryAr":"غسيل كيميائي","captionEn":"Removing sand and salt encrustation to boost cooling efficiency by 34%.","captionAr":"إزالة الرواسب والأتربة وتحسين كفاءة التبريد وخفض استهلاك الطاقة بنسبة ٣٤٪.","locationEn":"Dammam Corniche","locationAr":"كورنيش الدمام","active":true},{"id":"gal-3","image":"https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1000&q=80","titleEn":"Rooftop Concealed Package Servicing","titleAr":"صيانة وحدات الباكج السطحية المدمجة","categoryEn":"Rooftop Package","categoryAr":"وحدات سطحية","captionEn":"Blower fan replacement and belt tensioning for residential compound.","captionAr":"تبديل محركات الدفع وتعديل سيور المراوح لمجمع سكني راقٍ بالظهران.","locationEn":"Dhahran Hills","locationAr":"تلال الظهران","active":true},{"id":"gal-4","image":"https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=1000&q=80","titleEn":"Electronic Nitrogen Leak Detection","titleAr":"كشف تسريبات الغاز بالنيتروجين المضغوط","categoryEn":"Diagnostics","categoryAr":"كشف وفحص","captionEn":"High-precision micro-leak repair on concealed copper lines.","captionAr":"معالجة تسريب مجهري دقيق في خطوط النحاس المدفونة دون تكسير.","locationEn":"Qatif","locationAr":"القطيف","active":true},{"id":"gal-5","image":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1000&q=80","titleEn":"Air Duct Sanitization & Airflow Balancing","titleAr":"تعقيم مجاري الهواء وموازنة التدفق","categoryEn":"Air Quality","categoryAr":"جودة الهواء","captionEn":"UV sanitization and bacterial decontamination in private medical clinic.","captionAr":"تعقيم بالأشعة فوق البنفسجية وتطهير شامل لمجاري الهواء لمركز طبي.","locationEn":"Jubail Industrial","locationAr":"الجبيل الصناعية","active":true},{"id":"gal-6","image":"https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=1000&q=80","titleEn":"Luxury Villa Multi-Split Overhaul","titleAr":"صيانة وتجديد منظومة تكييف قصر سكني","categoryEn":"Residential Villa","categoryAr":"فلل وقصور","captionEn":"Full 14-unit servicing, condensate pump install, and smart thermostat sync.","captionAr":"صيانة كاملة لـ ١٤ وحدة سبليت وكونسيلد وتركيب مضخات تصريف وثرموستات ذكي.","locationEn":"Saihat","locationAr":"سيهات","active":true}]'::jsonb) on conflict(sector,section_key) do nothing;
