insert into public.hard_sector_sections(sector,section_key,body) values('hvac','maintenance_guide','[{"id":"sc-1","titleEn":"Condenser Coil Chemical Pressure Wash","titleAr":"الغسيل الكيميائي لملفات المكثف الخارجية","descEn":"Removes baked-in sand and salt deposits to allow proper heat rejection in 48°C+ ambient temperatures.","descAr":"إزالة الأتربة والتكلسات الملحية لضمان تشتيت الحرارة بفاعلية عند تجاوز درجات الحرارة ٤٨ مئوية.","importanceEn":"Critical","importanceAr":"بالغ الأهمية","iconName":"Sparkles"},{"id":"sc-2","titleEn":"Refrigerant Charge & Subcooling Verification","titleAr":"معايرة ضغط غاز الفريون ودرجة التبريد الفائق","descEn":"Ensures optimal refrigerant levels to prevent compressor overheating and maintain sub-zero coil temperatures.","descAr":"التأكد من دقة كمية الغاز لحماية الضاغط من السخونة وضمان أعلى إنتاجية للبرودة.","importanceEn":"High","importanceAr":"أهمية عالية","iconName":"Gauge"},{"id":"sc-3","titleEn":"Drain Line & Condensate Pan Anti-Algae Treatment","titleAr":"تطهير مجاري تصريف المياه لمنع الانسداد والتسريب","descEn":"Clears accumulated slime and bacterial mold preventing internal ceiling leaks and musty odors.","descAr":"تنظيف وتطهير حوض التصريف بالسوائل المعقمة لمنع طفح المياه وتلف الجبس والدهانات.","importanceEn":"High","importanceAr":"أهمية عالية","iconName":"Droplets"},{"id":"sc-4","titleEn":"Electrical Contactor & Capacitor Amp Testing","titleAr":"فحص استهلاك الأمبير للكونتاكتور ومكثفات التشغيل","descEn":"Weak capacitors cause sudden motor burnouts under heavy summer start loads; early replacement saves compressors.","descAr":"فحص كفاءة الكابستر، حيث يتسبب ضعفه في احتراق محرك الكمبروسر عند ضغط التشغيل المستمر.","importanceEn":"Preventative","importanceAr":"فحص وقائي","iconName":"Zap"},{"id":"wc-2","titleEn":"Deep Duct Cleaning & HEPA Filter Upgrades","titleAr":"تعقيم مجاري الهواء واستبدال الفلاتر عالية الكفاءة","descEn":"Off-peak season is the ideal window to sanitize ductwork and replace pleated allergen filters.","descAr":"فترة الشتاء هي التوقيت المثالي لتعقيم قنوات الهواء وتغيير الفلاتر للتخلص من مسببات الحساسية.","importanceEn":"Air Quality","importanceAr":"جودة الهواء","iconName":"Wind"},{"id":"wc-3","titleEn":"Outdoor Unit Protective De-scaling & Cover Service","titleAr":"معالجة الهيكل الخارجي ضد الصدأ وتأثير الرطوبة","descEn":"Applying anti-corrosion protective coatings to outdoor chassis exposed to coastal sea breezes.","descAr":"رش طبقة حماية عازلة لمنع تأكل الصاج الخارجي بفعل الرطوبة والرياح الساحلية المحملة بالأملاح.","importanceEn":"Protection","importanceAr":"حماية وتمديد عمر","iconName":"Shield"}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('hvac','reviews','[{"id":"rev-1","nameEn":"Eng. Khalid Al-Otaibi","nameAr":"م. خالد العتيبي","cityEn":"Al Khobar (Al Hada)","cityAr":"الخبر (حي الهدى)","rating":5,"quoteEn":"During the 49°C heatwave in July, our central VRF failed. The HARD emergency team arrived in 35 minutes, diagnosed a faulty inverter board, replaced it with a genuine part, and had the entire villa chilled before sunset. Exceptional professionalism.","quoteAr":"تعطل نظام التكييف المركزي بالفيلا خلال ذروة الصيف ودرجة الحرارة قاربت ٥٠ مئوية. وصل فريق طوارئ هارد خلال ٣٥ دقيقة وشخصوا عطل لوحة الإنفرتر واستبدلوها بقطعة أصلية وعاد التبريد بكفاءة مبهرة.","serviceEn":"Emergency VRF Repair","serviceAr":"صيانة طوارئ VRF","date":"2026-07-14","active":true},{"id":"rev-2","nameEn":"Fahad Al-Dossary","nameAr":"فهد الدوسري","cityEn":"Dammam (Al Faisaliyah)","cityAr":"الدمام (الفيصلية)","rating":5,"quoteEn":"The chemical coil cleaning service completely transformed our ACs. The air smells fresh, the cooling is ice-cold even at 2 PM, and our monthly electric bill dropped by almost 28%. Highest recommendation.","quoteAr":"الغسيل الكيميائي العميق لـ ٨ مكيفات سبليت بالمنزل فرق معنا بشكل جذري؛ اختفت الروائح المكتومة وصار التبريد قوي جداً حتى في عز القايلة، وفاتورة الكهرباء نزلت بشكل ملحوظ.","serviceEn":"Deep Chemical Washing","serviceAr":"غسيل كيميائي شامل","date":"2026-06-28","active":true},{"id":"rev-3","nameEn":"Sara Al-Mansoori","nameAr":"سارة المنصوري","cityEn":"Dhahran","cityAr":"الظهران","rating":5,"quoteEn":"We signed an Annual Maintenance Contract (AMC) for our commercial office building with HARD. Their scheduled quarterly visits, prompt technician logs, and zero downtime have made facility management effortless.","quoteAr":"وقعنا عقد صيانة سنوي (AMC) لمبنى مكاتبنا بالظهران. التزامهم بالمواعيد الدورية والتقارير الفنية الموثقة أراحنا تماماً من مفاجآت تعطل التكييف أثناء ساعات العمل.","serviceEn":"Annual AMC Contract","serviceAr":"عقد صيانة سنوي","date":"2026-05-19","active":true},{"id":"rev-4","nameEn":"Dr. Tariq Al-Ghamdi","nameAr":"د. طارق الغامدي","cityEn":"Qatif (Al Shati)","cityAr":"القطيف (الشاطئ)","rating":5,"quoteEn":"Honest pricing with no guesswork. Other companies claimed my compressor was dead, but the HARD technician proved it was merely a blown capacitor and saved me 4,000 SAR. Genuine integrity.","quoteAr":"أمانة ومهنية نادرة. شركتان سابقتان أخبروني بضرورة تبديل الكمبروسر بتكلفة باهظة، بينما فني هارد فحص بدقة واكتشف أن المشكلة فقط في كابستر الكهرباء ووفر علي آلاف الريالات.","serviceEn":"Electrical Diagnostic & Repair","serviceAr":"فحص كهربائي وإصلاح","date":"2026-04-10","active":true}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_sector_sections(sector,section_key,body) values('hvac','faq','[{"id":"faq-1","questionEn":"How often should AC units be chemically deep-cleaned in the Eastern Province?","questionAr":"كم مرة ينصح بالغسيل الكيميائي العميق لمكيفات الهواء في المنطقة الشرقية؟","answerEn":"Due to high humidity and fine coastal dust in the Eastern Province (Dammam, Khobar, Qatif, Jubail), we recommend a deep chemical coil wash twice a year — once before the extreme summer peak (April/May) and once post-summer (October). Filters should be rinsed monthly.","answerAr":"نظراً لارتفاع الرطوبة والغبار الساحلي في مدن الشرقية (الخبر، الدمام، القطيف، الجبيل)، نوصي بالغسيل الكيميائي العميق مرتين سنوياً؛ الأولى قبل بداية ذروة الصيف (أبريل/مايو)، والثانية بعد انكسار الحرارة (أكتوبر)، مع غسل فلاتر الهواء بانتظام كل شهر."},{"id":"faq-2","questionEn":"What is the response time for 24/7 emergency AC breakdowns?","questionAr":"ما هي المدة الزمنية لوصول فريق طوارئ التكييف في الحالات العاجلة؟","answerEn":"Our mobile service units are positioned across Dammam, Khobar, and Dhahran, with average on-site arrival within 30 to 45 minutes for urgent calls. Immediate phone triage and dispatch request review occur upon submission.","answerAr":"تتوزع سيارات الخدمة الميدانية السريعة في نقاط حيوية بالخبر والدمام والظهران، ويصل الفني لموقعك خلال ٣٠ إلى ٤٥ دقيقة في المتوسط للبلاغات الطارئة، مع توجيه هاتفي فوري ومراجعة طلب الإسناد عند الإرسال."},{"id":"faq-3","questionEn":"Do you use genuine certified refrigerants (R410A / R32)?","questionAr":"هل تستخدمون فريون أصلي معتمد وتتحققون من عدم وجود تسريب؟","answerEn":"Yes, we exclusively use 100% pure American and European brand refrigerants (Honeywell, Chemours/DuPont, Arkema). We never charge refrigerant without performing a vacuum decay test and nitrogen leak check first, ensuring long-term compressor safety.","answerAr":"نعم بالتأكيد، نستخدم حصراً عبوات غاز تبريد أصلية ١٠٠٪ من كبرى الشركات العالمية. ولا نقوم بتعبئة الغاز مطلقاً قبل إجراء فحص تسريب بالنيتروجين واختبار الفاكيوم الإلكتروني لضمان سلامة الضاغط."},{"id":"faq-4","questionEn":"What is included in an Annual Maintenance Contract (AMC)?","questionAr":"ما الذي تشمله عقود الصيانة السنوية (AMC) للفلل والمباني التجارية؟","answerEn":"Our AMC includes 4 quarterly scheduled comprehensive checkups, deep coil chemical wash, electrical amp balancing, drain unclogging, emergency dispatch priority with zero callout fees, and a 20% discount on all replacement spare parts.","answerAr":"تشمل عقود الصيانة السنوية ٤ زيارات دورية ربع سنوية، غسيل كيميائي للكويلات، فحص الأمبير والثرموستات، تنظيف مجاري التصريف، أولوية قصوى للطوارئ على مدار الساعة بدون رسوم معاينة، مع خصم ٢٠٪ على قطع الغيار."},{"id":"faq-5","questionEn":"What is the difference between regular water washing and chemical cleaning?","questionAr":"ما الفرق بين الغسيل العادي بالماء والغسيل الكيميائي المتخصص؟","answerEn":"Water washing only removes surface-level dust on filters. Chemical washing utilizes specialized, coil-safe foaming agents that dissolve deep-seated oily films, salt encrustation, mold, and bacterial colonies trapped deep inside the aluminum fins, restoring factory airflow and cooling power.","answerAr":"الغسيل العادي بالماء ينظف الأتربة السطحية فقط، بينما الغسيل الكيميائي يستخدم محاليل رغوية خاصة آمنة تزيل الدهون، التكلسات الملحية، والبكتيريا المتغلغلة بين زعانف الألمنيوم الدقيقة، مما يعيد تدفق الهواء وقوة التبريد الأصلية للجهاز."},{"id":"faq-6","questionEn":"Do you offer written warranties on AC repairs and compressor replacements?","questionAr":"هل تقدمون ضماناً خطياً معتمداً على أعمال الإصلاح وقطع الغيار؟","answerEn":"Yes, all repair operations come with an official warranty certificate: 3 to 6 months on standard repairs and up to 1 year on compressor and motor replacements with genuine parts.","answerAr":"نعم، نقدم شهادة ضمان رسمية معتمدة تمتد من ٣ إلى ٦ أشهر على أعمال الإصلاح العامة، وتصل إلى سنة كاملة على الكمبروسرات والمحركات المستبدلة بقطع أصلية."},{"id":"faq-7","questionEn":"Can HARD maintain centralized VRF, Chiller, and Rooftop Package units?","questionAr":"هل تمتلك هارد القدرة على صيانة شيلرات التبريد المركزي ووحدات الباكج السطحية؟","answerEn":"Yes, our team includes certified electro-mechanical engineers equipped with industrial diagnostic manifolds, oil acid test kits, and thermal imaging cameras specifically for heavy commercial VRF, chilled water systems, and rooftop package units.","answerAr":"نعم، يضم فريقنا مهندسين كهروميكانيكيين متخصصين مجهزين بأحدث أجهزة قياس الضغط الصناعية، كاميرات الفحص الحراري، وأجهزة فحص حموضة الزيت لصيانة الشيلرات المركزية وأنظمة VRF والباكج للمباني الكبرى."}]'::jsonb) on conflict(sector,section_key) do nothing;
insert into public.hard_company_content(kind,id,body) values('stories','test-1','{"id":"test-1","name":{"en":"Eng. Khalid Al-Zahrani","ar":"م. خالد الزهراني"},"role":{"en":"Managing Director, Energy Investments","ar":"مدير تنفيذي لاستثمارات الطاقة"},"location":{"en":"Dhahran / Al Khobar","ar":"الظهران / الخبر"},"avatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=80","rating":5,"quote":{"en":"Listing my luxury villa in Al Khobar with HARD was the best decision. Their cinematic media marketing and verified buyer network brought 3 qualified cash offers in under two weeks. We closed smoothly above our initial reserve price.","ar":"كان عرض قصرنا في الخبر مع شركة هارد للعقارات أفضل قرار اتخذته. حملتهم الإعلامية السينمائية وشبكة المشترين المعتمدين حققت 3 عروض شراء نقدية خلال أقل من أسبوعين، وتم الإفراغ بسلاسة تفوق توقعاتنا."},"dealHighlight":{"en":"Sold Khobar Waterfront Villa in 11 Days","ar":"بيع فيلا كورنيش الخبر في 11 يوماً"},"category":"seller"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.hard_company_content(kind,id,body) values('stories','test-2','{"id":"test-2","name":{"en":"Dr. Fatima Al-Mansoor","ar":"د. فاطمة المنصور"},"role":{"en":"Healthcare Executive & Portfolio Investor","ar":"مستثمرة عقارية وقيادية في القطاع الصحي"},"location":{"en":"Dammam / Riyadh","ar":"الدمام / الرياض"},"avatar":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=300&q=80","rating":5,"quote":{"en":"As an active investor acquiring prime residential towers and commercial land in the Eastern Province, the market intelligence and REGA-verified transaction advisory provided by HARD were truly exceptional.","ar":"بصفتي مستثمرة في الأراضي والمجمعات السكنية بالمنطقة الشرقية، كانت دراسات السوق والوساطة الاحترافية الموثقة عبر منصات الهيئة العامة للعقار مع هارد على أعلى مستوى من الدقة والاحترافية."},"dealHighlight":{"en":"Acquired 2 Prime Waterfront Assets (28M SAR)","ar":"شراء أصلين بحريين فاخرين بقيمة 28 مليون ريال"},"category":"investor"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.hard_company_content(kind,id,body) values('stories','test-3','{"id":"test-3","name":{"en":"Mark & Sarah Thompson","ar":"مارك وسارة طومسون"},"role":{"en":"Executive Relocation Clients","ar":"عائلة تنفيذية مقيمة بالمنطقة الشرقية"},"location":{"en":"Dhahran Hills / London","ar":"تلال الظهران / لندن"},"avatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80","rating":5,"quote":{"en":"Relocating to Saudi Arabia, navigating local title registries and neighborhood selections seemed daunting. The advisors at HARD guided us through every step, finding our dream family home in Dhahran Hills completely hassle-free.","ar":"أثناء انتقالنا للعمل في المملكة، ساعدنا فريق هارد في اختيار الحي المثالي واستكمال كافة إجراءات التوثيق السكني بسلاسة تامة وشفافية مطلقة في تلال الظهران."},"dealHighlight":{"en":"Family Home in Dhahran Hills","ar":"شراء منزل عائلي فاخر في تلال الظهران"},"category":"buyer"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','general_contact','{"formType":"general_contact","sector":"group","title":{"ar":"تواصل معنا (المقر الرئيسي)","en":"General Inquiry (Group HQ)"},"description":{"ar":"أرسل لنا استفسارك وسيقوم فريق خدمة العملاء بالتواصل معك خلال 24 ساعة.","en":"Send us your inquiry and our client relations team will contact you within 24 hours."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"placeholder":{"ar":"أدخل اسمك الكريم","en":"Enter your full name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email Address"},"placeholder":{"ar":"name@domain.com","en":"name@domain.com"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم الهاتف / الواتساب","en":"Phone / WhatsApp"},"placeholder":{"ar":"+966 5x xxx xxxx","en":"+966 5x xxx xxxx"},"required":true,"isSystemCritical":true},{"id":"preferredContactMethod","type":"select","label":{"ar":"وسيلة التواصل المفضلة","en":"Preferred Contact Method"},"required":false,"options":[{"value":"whatsapp","label":{"ar":"واتساب (WhatsApp)","en":"WhatsApp"}},{"value":"phone","label":{"ar":"اتصال هاتفي","en":"Phone Call"}},{"value":"email","label":{"ar":"بريد إلكتروني","en":"Email"}}]},{"id":"message","type":"textarea","label":{"ar":"تفاصيل الاستفسار","en":"Inquiry Details"},"placeholder":{"ar":"اكتب تفاصيل طلبك هنا...","en":"Describe your inquiry here..."},"required":false}],"confirmationCopy":{"title":{"ar":"تم إرسال استفسارك بنجاح","en":"Inquiry Submitted Successfully"},"message":{"ar":"شكراً لتواصلك مع مجموعة HARD. تم تسجيل طلبك وسيقوم مستشارنا بالتواصل معك قريباً.","en":"Thank you for contacting HARD Group. Your inquiry has been registered and a specialist will contact you shortly."}},"workflowSettings":{"trackingPrefix":"CNT","dispatchDepartment":"Customer Relations","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','property_inquiry','{"formType":"property_inquiry","sector":"realestate","title":{"ar":"استفسار عن عقار","en":"Property Inquiry"},"description":{"ar":"استفسر عن العقارات المتاحة للبيع أو الإيجار واستلم التفاصيل من مستشارنا العقاري.","en":"Inquire about properties for sale or rent and receive details from our advisor."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"placeholder":{"ar":"أدخل اسمك الكريم","en":"Enter full name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"placeholder":{"ar":"name@example.com","en":"name@example.com"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم الجوال","en":"Mobile Number"},"placeholder":{"ar":"+966 5xxxxxxxx","en":"+966 5xxxxxxxx"},"required":true,"isSystemCritical":true},{"id":"preferredContactMethod","type":"select","label":{"ar":"طريقة التواصل المفضلة","en":"Preferred Contact"},"required":false,"options":[{"value":"whatsapp","label":{"ar":"واتساب","en":"WhatsApp"}},{"value":"phone","label":{"ar":"اتصال مباشر","en":"Direct Call"}}]},{"id":"message","type":"textarea","label":{"ar":"الرسالة أو الاستفسار الخاصة","en":"Message or Special Request"},"required":false}],"confirmationCopy":{"title":{"ar":"تم تسجيل طلب الاستفسار","en":"Property Inquiry Received"},"message":{"ar":"تم توجيه طلبك لمستشار العقارات المعتمد لهذه الوحدة وسيتواصل معك مباشرة.","en":"Your inquiry was routed to the designated advisor for this property."}},"workflowSettings":{"trackingPrefix":"INQ","dispatchDepartment":"Real Estate Sales","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','list_property','{"formType":"list_property","sector":"realestate","title":{"ar":"عرض عقارك للبيع أو الإيجار","en":"List Your Property"},"description":{"ar":"اعرض عقارك عبر منصتنا للوصول إلى قاعدة عملائنا ونخبة المستثمرين.","en":"List your property with us to reach our verified buyer network."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"اسم المالك / الوكيل","en":"Owner / Agent Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم التواصل","en":"Phone Number"},"required":true,"isSystemCritical":true},{"id":"propertyType","type":"select","label":{"ar":"نوع العقار","en":"Property Type"},"required":true,"options":[{"value":"villa","label":{"ar":"فيلا سكني","en":"Residential Villa"}},{"value":"commercial","label":{"ar":"مبنى تجاري / مكاتب","en":"Commercial Building / Offices"}},{"value":"land","label":{"ar":"أرض خام / استثمارية","en":"Plot / Raw Land"}}]},{"id":"city","type":"text","label":{"ar":"المدينة والحي","en":"City & District"},"required":true}],"confirmationCopy":{"title":{"ar":"تم استقبال طلب إدراج العقار","en":"Property Listing Request Received"},"message":{"ar":"سيقوم فريق الوساطة والأصول بمراجعة بيانات العقار والتواصل لتأكيد الإدراج.","en":"Our brokerage team will verify your property details and contact you for listing confirmation."}},"workflowSettings":{"trackingPrefix":"LST","dispatchDepartment":"Property Listings","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','valuation_request','{"formType":"valuation_request","sector":"realestate","title":{"ar":"طلب تقييم وتثمين عقاري","en":"Property Valuation Request"},"description":{"ar":"احصل على تقييم عقاري معتمد ومعتمد من خبراء التقاط الهيكلي والتثمين.","en":"Request an accredited property valuation report from certified appraisers."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم الجوال","en":"Phone"},"required":true,"isSystemCritical":true},{"id":"propertyType","type":"text","label":{"ar":"نوع العقار المراد تقييمه","en":"Property Type for Valuation"},"required":true}],"confirmationCopy":{"title":{"ar":"تم استلام طلب التقييم","en":"Valuation Request Received"},"message":{"ar":"تم إحالة طلبكم إلى قسم التثمين العقاري لإعداد التقرير المبدئي.","en":"Your valuation request has been assigned to our certified appraisal department."}},"workflowSettings":{"trackingPrefix":"VAL","dispatchDepartment":"Valuation & Appraisal","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','book_viewing','{"formType":"book_viewing","sector":"realestate","title":{"ar":"حجز معاينة ميدانية","en":"Book On-Site Viewing"},"description":{"ar":"احجز موعداً لمعاينة العقار على الطبيعة برفقة مستشارنا.","en":"Schedule a private guided viewing on-site with our consultant."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم الجوال","en":"Phone Number"},"required":true,"isSystemCritical":true},{"id":"preferredDate","type":"date","label":{"ar":"التاريخ المفضل للمعاينة","en":"Preferred Viewing Date"},"required":true}],"confirmationCopy":{"title":{"ar":"تم تأكيد طلب معاينة العقار","en":"Viewing Booking Submitted"},"message":{"ar":"سيتواصل معك المستشار العقاري قبل الموعد بـ 24 ساعة لتأكيد التفاصيل.","en":"Our advisor will contact you 24 hours prior to confirm location details."}},"workflowSettings":{"trackingPrefix":"VIEW","dispatchDepartment":"Viewing Scheduling","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','project_inquiry','{"formType":"project_inquiry","sector":"construction","title":{"ar":"استفسار عن مشروع تطويري","en":"Development Project Inquiry"},"description":{"ar":"استفسر عن المشاريع التطويرية والفرص على الخارطة.","en":"Inquire about development projects and off-plan investment opportunities."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم الهاتف","en":"Phone Number"},"required":true,"isSystemCritical":true},{"id":"message","type":"textarea","label":{"ar":"تفاصيل الاستفسار","en":"Inquiry Message"},"required":false}],"confirmationCopy":{"title":{"ar":"تم استلام طلب المشروع","en":"Project Inquiry Received"},"message":{"ar":"تم تسجيل طلبك وسيقوم مسؤول المبيعات بالتواصل معك بخصوص كتيب المشروع والأسعار.","en":"Your request was routed to project sales for brochure and pricing delivery."}},"workflowSettings":{"trackingPrefix":"PRJ","dispatchDepartment":"Development Sales","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','construction_quote','{"formType":"construction_quote","sector":"construction","title":{"ar":"طلب تسعير وتسليم مفتاح","en":"Construction & Turnkey Quote"},"description":{"ar":"احصل على عرض سعر تفصيلي لمشروعك السكني أو التجاري.","en":"Request a detailed engineering construction cost estimate."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":true,"isSystemCritical":true},{"id":"phone","type":"tel","label":{"ar":"رقم التواصل","en":"Phone Number"},"required":true,"isSystemCritical":true},{"id":"projectType","type":"select","label":{"ar":"نوع المشروع","en":"Project Type"},"required":true,"options":[{"value":"villa","label":{"ar":"فيلا سكنية","en":"Villa"}},{"value":"commercial-building","label":{"ar":"مبنى تجاري","en":"Commercial Building"}},{"value":"duplex","label":{"ar":"دوبلكس","en":"Duplex"}},{"value":"residential-compound","label":{"ar":"مجمع سكني","en":"Residential Compound"}}]}],"confirmationCopy":{"title":{"ar":"تم استلام طلب التكاليف والتسعير","en":"Construction Quote Request Received"},"message":{"ar":"سيقوم المهندس المختص بدراسة الكميات والمواصفات وإعداد العرض الفني والمالي.","en":"Our estimation engineer will review quantities and specifications to prepare a formal quote."}},"workflowSettings":{"trackingPrefix":"CST","dispatchDepartment":"Contracting & Tenders","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','hvac_service','{"formType":"hvac_service","sector":"hvac","title":{"ar":"طلب خدمات التكييف والتهوية (HVAC)","en":"HVAC Service & Maintenance Request"},"description":{"ar":"حجز خدمات الصيانة، التركيب، والتصاميم الهندسية للتكييف.","en":"Book HVAC maintenance, installation, or engineering design services."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"fullName","type":"text","label":{"ar":"الاسم الكامل","en":"Full Name"},"required":true,"isSystemCritical":true},{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email"},"required":false},{"id":"phone","type":"tel","label":{"ar":"رقم الهاتف","en":"Phone Number"},"required":true,"isSystemCritical":true},{"id":"serviceType","type":"select","label":{"ar":"نوع خدمة التكييف","en":"Service Type"},"required":true,"options":[{"value":"maintenance","label":{"ar":"صيانة وقائية / دورية","en":"Preventive Maintenance"}},{"value":"installation","label":{"ar":"توريد وتركيب تكييف جديد","en":"Supply & Installation"}},{"value":"duct_design","label":{"ar":"تصميم وتشغيل مجاري الهواء (Duct)","en":"Duct Design & Contracting"}}]}],"confirmationCopy":{"title":{"ar":"تم تسجيل طلب خدمة التكييف","en":"HVAC Service Booking Submitted"},"message":{"ar":"تم تحويل الطلب إلى قسم الصيانة والتشغيل وسيتواصل معك الفني المباشر.","en":"Assigned to HVAC operations team; field technician will reach out for scheduling."}},"workflowSettings":{"trackingPrefix":"HVAC","dispatchDepartment":"HVAC Operations","notificationEmail":"info@hardgp.com","autoResponseEnabled":true}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('form','newsletter_signup','{"formType":"newsletter_signup","sector":"group","title":{"ar":"الاشتراك في النشرة البريدية","en":"Newsletter Subscription"},"description":{"ar":"اشترك للحصول على أحدث التقارير العقارية والفرص الاستثمارية.","en":"Subscribe to receive market insights and investment opportunities."},"schemaVersion":"1.0.0","updatedAt":"2026-11-18T09:48:13.957Z","updatedBy":"system","fields":[{"id":"email","type":"email","label":{"ar":"البريد الإلكتروني","en":"Email Address"},"required":true,"isSystemCritical":true}],"confirmationCopy":{"title":{"ar":"شكراً لاشتراكك","en":"Subscription Confirmed"},"message":{"ar":"تم إضافة بريدك الإلكتروني بنجاح لقائمة النشرة الإخبارية.","en":"Your email address has been added to our newsletter list."}},"workflowSettings":{"trackingPrefix":"SUB","dispatchDepartment":"Marketing & PR","notificationEmail":"info@hardgp.com","autoResponseEnabled":false}}'::jsonb) on conflict(kind,key) do nothing;
insert into public.hard_runtime_config(kind,key,body) values('calculator','hvac_published','{"id":"hvac_published","calculatorType":"hvac","version":1,"status":"published","titleAr":"حاسبة وفر الطاقة وكفاءة التكييف","titleEn":"HVAC Energy & Efficiency Cost Calculator","descriptionAr":"معايير حساب الأحمال والوفر المالي والبيئي متوافقة مع مواصفات ساسو (SASO/SEEC)","descriptionEn":"Cooling load and energy financial saving estimates aligned with SASO / SEEC standards","assumptionsAr":"تقدير الحمل 1 طن تبريد لكل 20م². تعرفة الكهرباء السكنية الأساسية 0.18 ر.س/ك.و.س.","assumptionsEn":"Cooling load based on 1 TR per 20 m². Standard SEC tariff benchmarked at 0.18 SAR/kWh.","coefficients":{"areaPerTonSqM":20,"btuPerTon":12000,"co2EmissionFactorKgPerKWh":0.52,"defaultTariffRateSAR":0.18,"tiers":{"split_standard":{"id":"split_standard","seer":13.5,"labelAr":"سبليت جداري / دولابي قياسي","labelEn":"Standard Wall Split","seerDisplay":"13.5 SEER"},"inverter_high":{"id":"inverter_high","seer":18,"labelAr":"انفرتر ذكي عالي الكفاءة","labelEn":"High Efficiency Inverter","seerDisplay":"18.0 SEER (Inverter)"},"package_unit":{"id":"package_unit","seer":15.5,"labelAr":"وحدة مدمجة للمباني التجارية","labelEn":"Rooftop Package Unit","seerDisplay":"15.5 SEER"},"vrf_central":{"id":"vrf_central","seer":21,"labelAr":"نظام VRF المركزي المتغير","labelEn":"Smart Central VRF","seerDisplay":"21.0+ SEER (Smart VRF)"}},"baselineOptions":[{"id":"10.5","seer":10.5,"labelAr":"نظام تقليدي قديم (10.5 SEER)","labelEn":"Legacy Non-Inverter (10.5 SEER)"},{"id":"11.5","seer":11.5,"labelAr":"تكييف مركزي قياسي (11.5 SEER)","labelEn":"Standard Central Unit (11.5 SEER)"},{"id":"10.0","seer":10,"labelAr":"نظام شيلر تبريد قديم (10.0 SEER)","labelEn":"Legacy Chiller System (10.0 SEER)"}]},"updatedAt":"2026-11-18T09:48:13.968Z","publishedAt":"2026-11-18T09:48:13.968Z"}'::jsonb) on conflict(kind,key) do nothing;
